# -*- coding: utf-8 -*-
"""Идемпотентная схема модуля ремонта и ТО."""

REPAIR_SCHEMA = """
CREATE TABLE IF NOT EXISTS repair_types(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,description TEXT,active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS fault_categories(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,severity TEXT DEFAULT 'обычная',active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS vehicle_systems(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,parent_id INTEGER,active INTEGER DEFAULT 1 CHECK(active IN(0,1)),FOREIGN KEY(parent_id) REFERENCES vehicle_systems(id));
CREATE TABLE IF NOT EXISTS workshops(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,address TEXT,active INTEGER DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS repair_posts(id INTEGER PRIMARY KEY,workshop_id INTEGER NOT NULL,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,post_type TEXT,active INTEGER DEFAULT 1 CHECK(active IN(0,1)),FOREIGN KEY(workshop_id) REFERENCES workshops(id));
CREATE TABLE IF NOT EXISTS warehouses(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,responsible_user_id INTEGER,active INTEGER DEFAULT 1 CHECK(active IN(0,1)),FOREIGN KEY(responsible_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS parts(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,unit TEXT DEFAULT 'шт',warehouse_id INTEGER,stock_qty REAL DEFAULT 0 CHECK(stock_qty>=0),reserved_qty REAL DEFAULT 0 CHECK(reserved_qty>=0 AND reserved_qty<=stock_qty),min_qty REAL DEFAULT 0 CHECK(min_qty>=0),unit_price REAL DEFAULT 0 CHECK(unit_price>=0),active INTEGER DEFAULT 1 CHECK(active IN(0,1)),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id));
CREATE TABLE IF NOT EXISTS operation_catalog(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,vehicle_system_id INTEGER,repair_type_id INTEGER,norm_hours REAL DEFAULT 0 CHECK(norm_hours>=0),default_price REAL DEFAULT 0 CHECK(default_price>=0),active INTEGER DEFAULT 1 CHECK(active IN(0,1)),FOREIGN KEY(vehicle_system_id) REFERENCES vehicle_systems(id),FOREIGN KEY(repair_type_id) REFERENCES repair_types(id));
CREATE TABLE IF NOT EXISTS repair_sequences(document_type TEXT NOT NULL,year INTEGER NOT NULL CHECK(year>=2000),last_number INTEGER DEFAULT 0 CHECK(last_number>=0),PRIMARY KEY(document_type,year));
CREATE TABLE IF NOT EXISTS repair_requests(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,created_by INTEGER,bus_id INTEGER NOT NULL,source TEXT DEFAULT 'ручная',incident_id INTEGER,waybill_id INTEGER,route_id INTEGER,driver_id INTEGER,repair_type_id INTEGER,fault_category_id INTEGER,status TEXT DEFAULT 'новая',priority TEXT DEFAULT 'обычный',odometer REAL CHECK(odometer IS NULL OR odometer>=0),description TEXT NOT NULL,location TEXT,desired_at TEXT,accepted_at TEXT,closed_at TEXT,repeated INTEGER DEFAULT 0 CHECK(repeated IN(0,1)),repeated_from_id INTEGER,cancel_reason TEXT,FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(waybill_id) REFERENCES waybills(id),FOREIGN KEY(route_id) REFERENCES routes(id),FOREIGN KEY(driver_id) REFERENCES drivers(id),FOREIGN KEY(repair_type_id) REFERENCES repair_types(id),FOREIGN KEY(fault_category_id) REFERENCES fault_categories(id),FOREIGN KEY(repeated_from_id) REFERENCES repair_requests(id));
CREATE TABLE IF NOT EXISTS repair_orders(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,request_id INTEGER UNIQUE,bus_id INTEGER NOT NULL,repair_type_id INTEGER,status TEXT DEFAULT 'черновик',workshop_id INTEGER,repair_post_id INTEGER,responsible_master_id INTEGER,planned_start TEXT,planned_end TEXT,actual_start TEXT,actual_end TEXT,diagnosis TEXT,result TEXT,odometer_in REAL CHECK(odometer_in IS NULL OR odometer_in>=0),odometer_out REAL CHECK(odometer_out IS NULL OR odometer_out>=0),planned_hours REAL DEFAULT 0 CHECK(planned_hours>=0),actual_hours REAL DEFAULT 0 CHECK(actual_hours>=0),labor_cost REAL DEFAULT 0 CHECK(labor_cost>=0),parts_cost REAL DEFAULT 0 CHECK(parts_cost>=0),external_cost REAL DEFAULT 0 CHECK(external_cost>=0),other_cost REAL DEFAULT 0 CHECK(other_cost>=0),total_cost REAL DEFAULT 0 CHECK(total_cost>=0),downtime_hours REAL DEFAULT 0 CHECK(downtime_hours>=0),release_allowed INTEGER DEFAULT 0 CHECK(release_allowed IN(0,1)),created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,closed_at TEXT,cancel_reason TEXT,FOREIGN KEY(request_id) REFERENCES repair_requests(id),FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(repair_type_id) REFERENCES repair_types(id),FOREIGN KEY(workshop_id) REFERENCES workshops(id),FOREIGN KEY(repair_post_id) REFERENCES repair_posts(id),FOREIGN KEY(responsible_master_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repair_order_status_events(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL,status TEXT NOT NULL,entered_at TEXT NOT NULL,left_at TEXT,changed_by INTEGER,FOREIGN KEY(order_id) REFERENCES repair_orders(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repair_order_workers(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL,worker_id INTEGER NOT NULL,role TEXT DEFAULT 'слесарь',status TEXT DEFAULT 'назначен',assigned_at TEXT DEFAULT CURRENT_TIMESTAMP,started_at TEXT,finished_at TEXT,planned_hours REAL DEFAULT 0 CHECK(planned_hours>=0),actual_hours REAL DEFAULT 0 CHECK(actual_hours>=0),hourly_rate REAL DEFAULT 0 CHECK(hourly_rate>=0),comment TEXT,UNIQUE(order_id,worker_id,role),FOREIGN KEY(order_id) REFERENCES repair_orders(id) ON DELETE CASCADE,FOREIGN KEY(worker_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repair_operations(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL,catalog_id INTEGER,vehicle_system_id INTEGER,worker_id INTEGER,sequence_no INTEGER DEFAULT 1 CHECK(sequence_no>0),name TEXT NOT NULL,status TEXT DEFAULT 'запланирована',norm_hours REAL DEFAULT 0 CHECK(norm_hours>=0),actual_hours REAL DEFAULT 0 CHECK(actual_hours>=0),price REAL DEFAULT 0 CHECK(price>=0),started_at TEXT,completed_at TEXT,result TEXT,additional_fault TEXT,FOREIGN KEY(order_id) REFERENCES repair_orders(id) ON DELETE CASCADE,FOREIGN KEY(catalog_id) REFERENCES operation_catalog(id),FOREIGN KEY(vehicle_system_id) REFERENCES vehicle_systems(id),FOREIGN KEY(worker_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repair_parts(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL,operation_id INTEGER,part_id INTEGER NOT NULL,requested_qty REAL DEFAULT 0 CHECK(requested_qty>=0),reserved_qty REAL DEFAULT 0 CHECK(reserved_qty>=0),issued_qty REAL DEFAULT 0 CHECK(issued_qty>=0),installed_qty REAL DEFAULT 0 CHECK(installed_qty>=0),returned_qty REAL DEFAULT 0 CHECK(returned_qty>=0),unit_price REAL DEFAULT 0 CHECK(unit_price>=0),status TEXT DEFAULT 'запрошено',cancelled_reason TEXT,FOREIGN KEY(order_id) REFERENCES repair_orders(id) ON DELETE CASCADE,FOREIGN KEY(operation_id) REFERENCES repair_operations(id),FOREIGN KEY(part_id) REFERENCES parts(id));
CREATE TABLE IF NOT EXISTS repair_inspections(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL,inspection_type TEXT NOT NULL,inspector_id INTEGER,inspected_at TEXT DEFAULT CURRENT_TIMESTAMP,result TEXT NOT NULL,release_allowed INTEGER DEFAULT 0 CHECK(release_allowed IN(0,1)),defects TEXT,comment TEXT,FOREIGN KEY(order_id) REFERENCES repair_orders(id) ON DELETE CASCADE,FOREIGN KEY(inspector_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS vehicle_repair_history(id INTEGER PRIMARY KEY,bus_id INTEGER NOT NULL,order_id INTEGER UNIQUE NOT NULL,request_number TEXT,order_number TEXT NOT NULL,repair_type TEXT,fault_category TEXT,opened_at TEXT,closed_at TEXT,odometer REAL CHECK(odometer IS NULL OR odometer>=0),result TEXT,operations_json TEXT DEFAULT '[]',workers_json TEXT DEFAULT '[]',parts_json TEXT DEFAULT '[]',total_cost REAL DEFAULT 0 CHECK(total_cost>=0),downtime_hours REAL DEFAULT 0 CHECK(downtime_hours>=0),snapshot_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(order_id) REFERENCES repair_orders(id));
CREATE TABLE IF NOT EXISTS repair_attachments(id INTEGER PRIMARY KEY,request_id INTEGER,order_id INTEGER,bus_id INTEGER NOT NULL,category TEXT,original_name TEXT NOT NULL,stored_name TEXT UNIQUE NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER CHECK(size_bytes>=0),uploaded_by INTEGER,uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES repair_requests(id),FOREIGN KEY(order_id) REFERENCES repair_orders(id),FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(uploaded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS maintenance_plans(id INTEGER PRIMARY KEY,bus_id INTEGER NOT NULL,repair_type_id INTEGER NOT NULL,name TEXT NOT NULL,interval_days INTEGER CHECK(interval_days IS NULL OR interval_days>0),interval_km REAL CHECK(interval_km IS NULL OR interval_km>0),last_date TEXT,last_odometer REAL CHECK(last_odometer IS NULL OR last_odometer>=0),next_date TEXT,next_odometer REAL CHECK(next_odometer IS NULL OR next_odometer>=0),warning_days INTEGER DEFAULT 7 CHECK(warning_days>=0),warning_km REAL DEFAULT 500 CHECK(warning_km>=0),active INTEGER DEFAULT 1 CHECK(active IN(0,1)),UNIQUE(bus_id,repair_type_id),FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(repair_type_id) REFERENCES repair_types(id));
CREATE TABLE IF NOT EXISTS maintenance_events(id INTEGER PRIMARY KEY,plan_id INTEGER NOT NULL,bus_id INTEGER NOT NULL,due_date TEXT,due_odometer REAL CHECK(due_odometer IS NULL OR due_odometer>=0),status TEXT DEFAULT 'запланировано',request_id INTEGER,order_id INTEGER,completed_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(plan_id) REFERENCES maintenance_plans(id),FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(request_id) REFERENCES repair_requests(id),FOREIGN KEY(order_id) REFERENCES repair_orders(id));
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY,number TEXT UNIQUE,part_id INTEGER NOT NULL,warehouse_id INTEGER NOT NULL,repair_part_id INTEGER,movement_type TEXT NOT NULL,quantity REAL NOT NULL CHECK(quantity>0),unit_price REAL DEFAULT 0 CHECK(unit_price>=0),movement_date TEXT DEFAULT CURRENT_TIMESTAMP,performed_by INTEGER,comment TEXT,FOREIGN KEY(part_id) REFERENCES parts(id),FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),FOREIGN KEY(repair_part_id) REFERENCES repair_parts(id),FOREIGN KEY(performed_by) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_repair_requests_vehicle ON repair_requests(bus_id); CREATE INDEX IF NOT EXISTS idx_repair_requests_status ON repair_requests(status); CREATE INDEX IF NOT EXISTS idx_repair_requests_fault_category ON repair_requests(fault_category_id); CREATE INDEX IF NOT EXISTS idx_repair_requests_created ON repair_requests(created_at);
CREATE INDEX IF NOT EXISTS idx_repair_orders_vehicle ON repair_orders(bus_id); CREATE INDEX IF NOT EXISTS idx_repair_orders_status ON repair_orders(status); CREATE INDEX IF NOT EXISTS idx_repair_orders_master ON repair_orders(responsible_master_id); CREATE INDEX IF NOT EXISTS idx_repair_orders_dates ON repair_orders(planned_start,planned_end); CREATE INDEX IF NOT EXISTS idx_repair_status_events_order ON repair_order_status_events(order_id,entered_at);
CREATE INDEX IF NOT EXISTS idx_repair_workers_worker ON repair_order_workers(worker_id,status); CREATE INDEX IF NOT EXISTS idx_repair_operations_order ON repair_operations(order_id,status); CREATE INDEX IF NOT EXISTS idx_repair_parts_order ON repair_parts(order_id,status); CREATE INDEX IF NOT EXISTS idx_repair_inspections_order ON repair_inspections(order_id,inspected_at); CREATE INDEX IF NOT EXISTS idx_repair_history_vehicle ON vehicle_repair_history(bus_id,closed_at); CREATE INDEX IF NOT EXISTS idx_repair_attachments_vehicle ON repair_attachments(bus_id); CREATE INDEX IF NOT EXISTS idx_maintenance_events_due_date ON maintenance_events(due_date,status); CREATE INDEX IF NOT EXISTS idx_stock_movements_part_date ON stock_movements(part_id,movement_date);
"""

BUS_MIGRATIONS = [("buses","modification","TEXT"),("buses","commissioned_at","TEXT"),("buses","body_number","TEXT"),("buses","engine_number","TEXT"),("buses","engine_type","TEXT"),("buses","ecological_class","TEXT"),("buses","assigned_route_id","INTEGER REFERENCES routes(id)"),("buses","last_to_date","TEXT"),("buses","warranty_status","TEXT"),("buses","photo_path","TEXT")]
REFERENCE_DATA = {"repair_types":[("TR","Текущий ремонт"),("TO1","ТО-1"),("TO2","ТО-2"),("KR","Капитальный ремонт")],"fault_categories":[("ENGINE","Двигатель"),("BRAKES","Тормозная система"),("ELECTRIC","Электрооборудование"),("BODY","Кузов")],"vehicle_systems":[("ENGINE","Двигатель"),("TRANSMISSION","Трансмиссия"),("BRAKES","Тормозная система"),("ELECTRIC","Электрооборудование")],"workshops":[("MAIN","Основная ремонтная зона")],"warehouses":[("MAIN","Основной склад")]}

def seed_repair_refs(con):
    for table, rows in REFERENCE_DATA.items():
        con.executemany(f"INSERT OR IGNORE INTO {table}(code,name) VALUES(?,?)", rows)
    workshop_id = con.execute("SELECT id FROM workshops WHERE code='MAIN'").fetchone()[0]
    con.execute("INSERT OR IGNORE INTO repair_posts(workshop_id,code,name) VALUES(?,?,?)",(workshop_id,"POST-1","Пост № 1"))

def migrate_repairs(con):
    con.executescript(REPAIR_SCHEMA)
    for table, column, definition in BUS_MIGRATIONS:
        if column not in {row[1] for row in con.execute(f"PRAGMA table_info({table})")}:
            con.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")
    con.execute("INSERT INTO repair_order_status_events(order_id,status,entered_at) SELECT ro.id,ro.status,COALESCE(ro.updated_at,ro.created_at,CURRENT_TIMESTAMP) FROM repair_orders ro WHERE NOT EXISTS (SELECT 1 FROM repair_order_status_events e WHERE e.order_id=ro.id)")
    seed_repair_refs(con)
